(function(root){
'use strict';
const letters='abcdefghijklmnopqrstuvwxyz',runes=Array.from('ᚨᛒᚲᛞᛖᚠᚷᚺᛁᛃᚴᛚᛗᚾᛟᛈᛩᚱᛊᛏᚢᚡᚹᛪᚣᛎ');
const encodeMap=Object.fromEntries(Array.from(letters).map((letter,i)=>[letter,runes[i]])),decodeMap=Object.fromEntries(runes.map((rune,i)=>[rune,letters[i]]));
function bounded(text){if(typeof text!=='string'||text.length>100000)throw Error('Text must be a string of at most 100,000 UTF-16 units');return text;}
function encode(text){return Array.from(bounded(text)).map(c=>/^[A-Za-z]$/.test(c)?encodeMap[c.toLowerCase()]:c).join('');}
function decode(text){return Array.from(bounded(text)).map(c=>decodeMap[c]||c).join('');}
function pack(text,edition='english'){bounded(text);if(!['english','iau'].includes(edition))throw Error('Unknown edition');return JSON.stringify({format:'rasniki-io',version:1,edition,text},null,2);}
function unpack(raw){if(typeof raw!=='string'||raw.length>1000000)throw Error('JSON input exceeds the import limit');let data;try{data=JSON.parse(raw);}catch(e){throw Error('Invalid JSON');}if(!data||typeof data!=='object'||Array.isArray(data)||data.format!=='rasniki-io'||data.version!==1||!['english','iau'].includes(data.edition))throw Error('Unsupported I/O record');return {format:data.format,version:1,edition:data.edition,text:bounded(data.text)};}
function command(raw){bounded(raw);if(raw.length>2000)throw Error('Commands are limited to 2000 characters');const line=raw.trim(),space=line.indexOf(' '),name=(space<0?line:line.slice(0,space)).toLowerCase(),arg=space<0?'':line.slice(space+1);switch(name){case 'help':return 'Commands: help | find QUERY | runes TEXT | english RUNES | math add|subtract|multiply|divide|gcd A B | bitflip BYTE BIT | show CATEGORY-ID';case 'find':{const rows=root.RasnikiSearch.find(root.RasnikiCatalog.entries,arg);return rows.slice(0,10).map(e=>e.id+' — '+e.name+' ['+e.status+']').join('\n')||'No catalogue matches.';}case 'runes':return encode(arg);case 'english':return decode(arg);case 'math':{const parts=arg.trim().split(/\s+/);if(parts.length!==3)throw Error('Use: math OPERATION INTEGER INTEGER');return root.RasnikiSearch.calculate(parts[1],parts[2],parts[0]);}case 'bitflip':{const parts=arg.trim().split(/\s+/);if(parts.length!==2)throw Error('Use: bitflip BYTE BIT');return String(root.RasnikiCatalog.bitflip(parts[0],parts[1]));}case 'show':{const e=root.RasnikiCatalog.entries.find(e=>e.id===arg.trim());if(!e)throw Error('Unknown category ID');return [e.name,e.status,e.purpose,e.review].join('\n');}default:throw Error('Unknown command. Use help.');}}
root.RasnikiIO={letters,runes,encode,decode,pack,unpack,command};
})(globalThis);
